#include <cstdio>
#include <cctype>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int, int> ii;

const int INF = 1000000000;
const int MAXN = 11;
const int MAXNODES = 205;
const int DIRECTIONS = 4;
const int dy[DIRECTIONS] = {-1, 0, 1, 0};
const int dx[DIRECTIONS] = {0, -1, 0, 1};

int n, t;
char a[MAXN][MAXN], b[MAXN][MAXN];
int br, bc;
int bum[MAXN][MAXN];
int dist[MAXN][MAXN];
bool pos[MAXN][MAXN];
int N;
int R[MAXN][MAXN];
vector<int> neighbors[MAXN];
int F[MAXN], P[MAXN];
int total_flow;

void BFS1()
{
    fill((int*)bum, (int*)bum + MAXN * MAXN, t);
    bum[br][bc] = 0;
    queue<ii> q; q.push(ii(br, bc));
    while (!q.empty()) {
        ii v = q.front(); int d = bum[v.first][v.second]; q.pop();
        for (int i = 0; i < DIRECTIONS; i++) {
            ii u = ii(v.first + dy[i], v.second + dx[i]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d + 1 < bum[u.first][u.second])
                bum[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void BFS2(int sr, int sc)
{
    fill((int*)dist, (int*)dist + MAXN * MAXN, INF);
    dist[sr][sc] = 0;
    fill((bool*)pos, (bool*)pos + MAXN * MAXN, false);
    pos[sr][sc] = true;
    queue<ii> q; q.push(ii(sr, sc));
    while (!q.empty()) {
        ii v = q.front(); int d = dist[v.first][v.second]; q.pop();
        pos[v.first][v.second] = d <= bum[v.first][v.second];
        if (d >= bum[v.first][v.second]) continue;
        for (int i = 0; i < DIRECTIONS; i++) {
            ii u = ii(v.first + dy[i], v.second + dx[i]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d + 1 < dist[u.first][u.second])
                dist[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void BFS(int sr, int sc, int d[][MAXN], int inf_value)
{
    fill((int*)d, (int*)d + MAXN * MAXN, inf_value);
    d[sr][sc] = 0;
    queue<ii> q; q.push(ii(sr, sc));
    while (!q.empty()) {
        ii v = q.front(); int d_v = d[v.first][v.second]; q.pop();
        for (int i = 0; i < DIRECTIONS; i++) {
            ii u = ii(v.first + dy[i], v.second + dx[i]);
            if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d_v + 1 < d[u.first][u.second])
                d[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int computeFlow()
{
    fill(F, F + N, 0); F[0] = INF;
    priority_queue<ii> pq; pq.push(ii(INF, 0));
    while (!pq.empty()) {
        int v = pq.top().second, f = pq.top().first; pq.pop();
        if (F[v] != f) continue;
        for (size_t i = 0; i < neighbors[v].size(); i++) {
            int u = neighbors[v][i];
            if (min(f, R[v][u]) > F[u]) F[u] = min(f, R[v][u]), P[u] = v, pq.push(ii(F[u], u));
        }
    }
    int v = N - 1;
    if (F[v] == 0) return 0;
    int flow = F[v];
    while (v != 0) {
        int u = P[v];
        R[u][v] -= flow; R[v][u] += flow;
        v = u;
    }
    return flow;
}

int main()
{
    scanf("%d %d", &n, &t);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            scanf(" %c", &a[i][j]);
            if (a[i][j] == 'Z') { br = i; bc = j; }
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &b[i][j]);
    BFS1();
    N = 2 * n * n + 2;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) if (isdigit(a[i][j]) && a[i][j] > '0') {
            int v = i * n + j + 1; R[0][v] = a[i][j] - '0'; neighbors[0].push_back(v); neighbors[v].push_back(0);
            BFS2(i, j);
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++) if (pos[i2][j2] && isdigit(b[i2][j2]) && b[i2][j2] > '0') {
                    int u = n * n + i2 * n + j2 + 1; R[v][u] = INF; neighbors[v].push_back(u); neighbors[u].push_back(v);
                }
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) if (isdigit(b[i][j]) && b[i][j] > '0') {
            int u = n * n + i * n + j + 1; R[u][N - 1] = b[i][j] - '0'; neighbors[u].push_back(N - 1); neighbors[N - 1].push_back(u);
        }
    int flow;
    total_flow = 0;
    while ((flow = computeFlow()) != 0) total_flow += flow;
    printf("%d\n", total_flow);
    return 0;
}
